/**
 * MettleUp's mark, logo E "Forged" (branding/mettleup/BRAND.md): a pointy-top hexagon cut into six
 * triangles (two top faces Molten, two side faces Forge, two bottom faces Slag) with an M knocked out
 * of it, so the background shows through the M. Geometry on the 512 grid, copied from
 * branding/mettleup/web/mark.svg (generated by branding/mettleup/_src/brand.py; keep in sync).
 *
 * The M is cut out here, in the numbers, rather than with an SVG mask or clip: each face's path is
 * the triangle plus the part of the M inside it, wound the other way, so a plain fill (nonzero)
 * leaves that part empty. That draws the same in react-native-svg, in resvg (share pictures in
 * tests) and in a browser, with nothing but <Path>.
 *
 * The wordmark "METTLEUP" is Manrope ExtraBold outlined to paths (branding/mettleup/web/
 * wordmark-text-dark.svg): BRAND.md never sets the name in another font in a logo position.
 * PURE: no React Native here (the share pictures and the tests use it too).
 */

/** The brand's own colours (BRAND.md). Never the gym's: no gym look repaints MettleUp's logo. */
export const METTLEUP_COLOURS = {
  /** top faces */
  molten: '#FF8A4C',
  /** side faces; the brand orange ("UP" in the wordmark in the app) */
  forge: '#F0662A',
  /** bottom faces */
  slag: '#C9481A',
} as const;

type Pt = readonly [number, number];

const C: Pt = [256, 256];
const TOP: Pt = [256, 52];
const UR: Pt = [432.67, 154];
const LR: Pt = [432.67, 358];
const BOT: Pt = [256, 460];
const LL: Pt = [79.33, 358];
const UL: Pt = [79.33, 154];

/** The hexagon's corners, clockwise from the top. */
export const HEX: readonly Pt[] = [TOP, UR, LR, BOT, LL, UL];

/** The M, cut through the hex (a 42-unit stroke, 11 units below the centre on purpose). */
export const M_CUT: readonly Pt[] = [
  [205, 346],
  [205, 245.8],
  [256, 306.71],
  [307, 245.8],
  [307, 346],
  [349, 346],
  [349, 188],
  [300.61, 188],
  [256, 241.29],
  [211.39, 188],
  [163, 188],
  [163, 346],
];

/** The six faces, lightest on top (BRAND.md: never change their order). */
const FACES: readonly { tri: readonly Pt[]; fill: string }[] = [
  { tri: [C, UL, TOP], fill: METTLEUP_COLOURS.molten },
  { tri: [C, TOP, UR], fill: METTLEUP_COLOURS.molten },
  { tri: [C, UR, LR], fill: METTLEUP_COLOURS.forge },
  { tri: [C, LL, UL], fill: METTLEUP_COLOURS.forge },
  { tri: [C, LR, BOT], fill: METTLEUP_COLOURS.slag },
  { tri: [C, BOT, LL], fill: METTLEUP_COLOURS.slag },
];

/** Twice the signed area (positive = clockwise on screen, y down). PURE. */
export function signedArea2(poly: readonly Pt[]): number {
  let s = 0;
  for (let i = 0; i < poly.length; i++) {
    const [x1, y1] = poly[i];
    const [x2, y2] = poly[(i + 1) % poly.length];
    s += x1 * y2 - x2 * y1;
  }
  return s;
}

/**
 * The part of `subject` inside the convex polygon `clip` (Sutherland–Hodgman). A concave subject
 * (the M) can come back with zero-width bridges along the clip's edges; they cover no area, so the
 * fill is right. PURE.
 */
export function clipToConvex(subject: readonly Pt[], clip: readonly Pt[]): Pt[] {
  const dir = Math.sign(signedArea2(clip));
  const inside = (p: Pt, a: Pt, b: Pt) => dir * ((b[0] - a[0]) * (p[1] - a[1]) - (b[1] - a[1]) * (p[0] - a[0])) >= 0;
  const cross = (p: Pt, q: Pt, a: Pt, b: Pt): Pt => {
    const [x1, y1] = p;
    const [x2, y2] = q;
    const [x3, y3] = a;
    const [x4, y4] = b;
    const den = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4);
    const t = ((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)) / den;
    return [x1 + t * (x2 - x1), y1 + t * (y2 - y1)];
  };
  let out: Pt[] = [...subject];
  for (let i = 0; i < clip.length && out.length; i++) {
    const a = clip[i];
    const b = clip[(i + 1) % clip.length];
    const input = out;
    out = [];
    for (let j = 0; j < input.length; j++) {
      const p = input[j];
      const q = input[(j + 1) % input.length];
      const pIn = inside(p, a, b);
      const qIn = inside(q, a, b);
      if (pIn) out.push(p);
      if (pIn !== qIn) out.push(cross(p, q, a, b));
    }
  }
  return out;
}

const r2 = (v: number) => Math.round(v * 100) / 100;
const ring = (poly: readonly Pt[]) => `M${poly.map(([x, y]) => `${r2(x)} ${r2(y)}`).join(' L')}Z`;

/** One face: its triangle, then the M's part inside it wound the other way (a hole). PURE. */
function facePath(tri: readonly Pt[]): string {
  const hole = clipToConvex(M_CUT, tri);
  if (hole.length < 3 || Math.abs(signedArea2(hole)) < 1e-6) return ring(tri);
  const opposite = Math.sign(signedArea2(hole)) !== Math.sign(signedArea2(tri)) ? hole : [...hole].reverse();
  return `${ring(tri)}${ring(opposite)}`;
}

/** The mark's six faces as paths on the 512 grid (M already cut out). */
export const MARK_FACES: readonly { d: string; fill: string }[] = FACES.map((f) => ({ d: facePath(f.tri), fill: f.fill }));

/** The square that holds the hex exactly (its points touch the top and bottom). */
export const MARK_BOX = { x: 52, y: 52, size: 408 } as const;

